from cardio_1 import a, G
a('PAO₂',[('P','Pression'),('A','Alvéolaire en'),('O₂','Oxygène')],'Pression alvéolaire en oxygène','<p>Pression partielle d’oxygène dans le gaz alvéolaire, calculée par l’équation des gaz alvéolaires : FiO₂ × (pression barométrique − pression de vapeur d’eau) − PaCO₂/0,8, soit environ 100 mmHg (13,3 kPa) au niveau de la mer en air ambiant. La différence avec la PaO₂ mesurée donne le gradient alvéolo-artériel. Le « A » majuscule désigne l’alvéole, le « a » minuscule le sang artériel.</p>','j96-aa')
a('P50',[('P','Pression partielle d’oxygène'),('50','à 50 % de saturation')],'Pression de demi-saturation de l’hémoglobine','<p>Pression partielle d’oxygène pour laquelle l’hémoglobine est saturée à 50 % ; environ 26,7 mmHg (3,5 kPa) chez l’adulte à pH 7,40 et 37 °C.</p>','j96-p50')
a('PvCO₂',[('P','Pression partielle'),('v','veineuse en'),('CO₂','dioxyde de carbone')],'Pression veineuse partielle en dioxyde de carbone','<p>Mesurée sur un gaz veineux périphérique ; une valeur normale rend une hypercapnie artérielle peu probable, une valeur élevée impose une gazométrie artérielle.</p>','j96-pvco2')
a('PtcCO₂',[('P','Pression partielle'),('tc','transcutanée en'),('CO₂','dioxyde de carbone')],'Pression transcutanée en dioxyde de carbone','<p>Mesure continue du CO₂ par une électrode cutanée chauffée ; méthode de choix pour dépister l’hypoventilation nocturne.</p>','j96-ptcco2')
a('cmH₂O',[('cm','centimètre'),('H₂O','d’eau')],'Centimètre d’eau','<p>Unité de pression utilisée en ventilation : 1 cmH₂O vaut environ 0,74 mmHg (98 Pa).</p>')
a('ROX',[('R','Respiratory rate (fréquence respiratoire)'),('OX','OXygenation (oxygénation : rapport SpO₂/FiO₂)')],'Index ROX','<p>Rapport (SpO₂/FiO₂)/fréquence respiratoire, proposé par Roca pour prédire le succès ou l’échec du haut débit nasal ; une valeur ≥ 4,88 à 12 heures est associée au succès (Roca, 2019). Aide pédagogique, non critère officiel.</p>','j96-rox')
a('FLORALI',[('FLORALI','nom d’essai dérivé de « high FLOw oxygen therapy in Resuscitation of patients with Acute Lung Injury », non strictement lettre à lettre')],'Essai FLORALI (2015)','<p>Essai multicentrique français comparant haut débit nasal, oxygène standard et ventilation non invasive dans l’insuffisance respiratoire hypoxémique aiguë non hypercapnique (New England Journal of Medicine, 2015).</p>','j96-florali')
a('IOTA',[('I','Improving'),('O','Oxygen'),('T','Therapy in'),('A','Acute illness')],'Méta-analyse IOTA (2018)','<p>Méta-analyse publiée dans le Lancet en 2018, comparant stratégies d’oxygène libérale et conservatrice chez l’adulte en situation aiguë ; la stratégie libérale était associée à une mortalité plus élevée.</p>','j96-hyperox')
a('DIABOLO',[('DIABOLO','nom d’essai français sur l’acétazolamide chez le patient BPCO ventilé, non développable lettre à lettre de façon vérifiée')],'Essai DIABOLO (2016)','<p>Essai randomisé publié dans JAMA en 2016 : l’acétazolamide n’a pas réduit significativement la durée de ventilation invasive des patients BPCO.</p>','j96-acetaz')
a('J96.0',[('J96','Insuffisance respiratoire'),('.0','aiguë')],'Insuffisance respiratoire aiguë, non classée ailleurs (CIM-10-GM 2024)','<p>Code complété par un cinquième caractère : 0 hypoxémique, 1 hypercapnique, 9 type non précisé. En cas d’insuffisance chronique préexistante, on ajoute un code J96.1-.</p>')
a('J96.00',[('J96.0','Insuffisance respiratoire aiguë'),('0','type I, hypoxémique')],'Insuffisance respiratoire aiguë de type I (CIM-10-GM 2024)','<p>PaO₂ &lt; 8,0 kPa sans hypercapnie, d’installation aiguë.</p>')
a('J96.01',[('J96.0','Insuffisance respiratoire aiguë'),('1','type II, hypercapnique')],'Insuffisance respiratoire aiguë de type II (CIM-10-GM 2024)','<p>PaCO₂ &gt; 6,0 kPa d’installation aiguë, avec ou sans hypoxémie.</p>')
a('J96.09',[('J96.0','Insuffisance respiratoire aiguë'),('9','type non précisé')],'Insuffisance respiratoire aiguë de type non précisé (CIM-10-GM 2024)','<p>Code à éviter lorsque la gazométrie permet de préciser le type.</p>')
a('J96.1',[('J96','Insuffisance respiratoire'),('.1','chronique')],'Insuffisance respiratoire chronique, non classée ailleurs (CIM-10-GM 2024)','<p>Code complété par un cinquième caractère (0, 1, 9). Une dépendance prolongée à l’aspiration ou à la ventilation s’ajoute par Z99.0 ou Z99.1.</p>')
a('J96.10',[('J96.1','Insuffisance respiratoire chronique'),('0','type I, hypoxémique')],'Insuffisance respiratoire chronique de type I (CIM-10-GM 2024)','<p>Hypoxémie chronique sans hypercapnie.</p>')
a('J96.11',[('J96.1','Insuffisance respiratoire chronique'),('1','type II, hypercapnique')],'Insuffisance respiratoire chronique de type II (CIM-10-GM 2024)','<p>Hypercapnie chronique, habituellement avec bicarbonate élevé et pH proche de la normale.</p>')
a('J96.19',[('J96.1','Insuffisance respiratoire chronique'),('9','type non précisé')],'Insuffisance respiratoire chronique de type non précisé (CIM-10-GM 2024)','<p>Code à éviter lorsque la gazométrie permet de préciser le type.</p>')
a('J96.9',[('J96','Insuffisance respiratoire'),('.9','sans précision de durée')],'Insuffisance respiratoire, sans précision (CIM-10-GM 2024)','<p>Code complété par un cinquième caractère (0, 1, 9).</p>')
a('J96.90',[('J96.9','Insuffisance respiratoire sans précision'),('0','type I, hypoxémique')],'Insuffisance respiratoire sans précision, type I (CIM-10-GM 2024)','<p>Durée inconnue, hypoxémie sans hypercapnie.</p>')
a('J96.91',[('J96.9','Insuffisance respiratoire sans précision'),('1','type II, hypercapnique')],'Insuffisance respiratoire sans précision, type II (CIM-10-GM 2024)','<p>Durée inconnue, hypercapnie.</p>')
a('J96.99',[('J96.9','Insuffisance respiratoire sans précision'),('9','type non précisé')],'Insuffisance respiratoire sans précision, type non précisé (CIM-10-GM 2024)','<p>Code résiduel.</p>')
a('Z99.0',[('Z99','Dépendance envers des machines et appareils auxiliaires'),('.0','aspirateur')],'Dépendance envers un aspirateur (CIM-10-GM 2024)','<p>Code additionnel en cas de besoin prolongé d’aspiration des sécrétions.</p>')
a('Z99.1',[('Z99','Dépendance envers des machines et appareils auxiliaires'),('.1','respirateur')],'Dépendance envers un respirateur (CIM-10-GM 2024)','<p>Code additionnel en cas de ventilation prolongée, y compris à domicile.</p>','j96-vnid')
a('R09.2',[('R09','Autres symptômes relatifs aux appareils circulatoire et respiratoire'),('.2','arrêt respiratoire')],'Arrêt respiratoire (CIM-10-GM 2024)','<p>Code CIM-10-GM 2024 qui comprend l’arrêt respiratoire et l’insuffisance cardio-respiratoire ; il est exclu des catégories J96 et R06.</p>')
if 'Henderson-Hasselbalch' not in G: a('Henderson-Hasselbalch',[('Henderson-Hasselbalch','nom propre : Lawrence Henderson et Karl Albert Hasselbalch ; ce n’est pas une abréviation')],'Équation d’Henderson-Hasselbalch','<p>pH = 6,1 + log [bicarbonate / (0,03 × PaCO₂)], avec le bicarbonate en mmol/L et la PaCO₂ en mmHg ; elle relie le pH au rapport entre bicarbonate et CO₂ dissous.</p>')
